            addRandomJitterVec3(&obj->squashX, 512.0f, 256.0f);
            addRandomJitterVec3(&sub->velX, 0.4f, 0.2f);
            sub->velY = 2.0f;
            playRandomBounceSoundAtNearestMarker(&obj->posX);
            obj->state = 0;
        }
    }
    switch (obj->state) {
