    header[1] = packed[1] & 0x3F;
    header[2] = (packed[2] >> 3) & 0x1F;
    header[3] = ((packed[2] & 7) << 2) | ((packed[3] >> 6) & 3);
    header[4] = (packed[3] >> 2) & 0xF;
    header[5] = ((packed[3] & 3) << 2) | ((packed[4] >> 6) & 3);
    header[6] = (packed[4] >> 3) & 7;
    header[7] = packed[4] & 7;
