	expBits = (bits >> 22);
	expBits &= 0x1ff;




	if ( expBits < 0x136 )
	{






		absAngle = (( angle ) > 0) ? ( angle ) : -( angle ) ;

		reduced = absAngle;

		quadrantFloat = reduced*rpi.d + 0.5;
		quadrant = (int)((( quadrantFloat ) >= 0.0) ? (( quadrantFloat ) + 0.5) : (( quadrantFloat ) - 0.5)) ;
