		quadrantFloat -= 0.5;

		reduced = reduced - quadrantFloat*pihi.d;
		reduced = reduced - quadrantFloat*pilo.d;	 

		reducedSq = reduced*reduced;

		poly = ((P[4].d*reducedSq + P[3].d)*reducedSq + P[2].d)*reducedSq + P[1].d;

		cosValue = reduced + (reduced*reducedSq)*poly;



